const cache = new Map();

export function getModuleAttributes(moduleId) {
    const cached = cache.get(moduleId);
    if (cached) {
        return cached;
    }
    const packed = PACKED[moduleId];
    if (!packed) {
        return null;
    }
    const rows = JSON.parse(packed).map(([path, type, c]) => {
        const row = { path, type };
        if (c !== undefined) {
            row.condition = CONDITIONS[c];
        }
        return row;
    });
    cache.set(moduleId, rows);
    return rows;
}
